<?php

declare(strict_types=1);

namespace Loop54\API\Request;

use Loop54\API\OpenAPI\Api\OtherApi;
use Loop54\API\OpenAPI\Api\UserInitiatedApi;

/**
 * Everything a {@see Request} needs to be sent to the engine: the low-level
 * autogenerated OpenAPI clients, plus the meta information and end-user
 * information that goes into the request headers.
 *
 * @internal Built by {@see \Loop54\API\Client::query()}.
 */
final readonly class RequestContext
{
    /**
     * @param string $apiVersion
     *    Currently supposed to be "V3".
     *
     * @param string $libVersion
     *    A string identifying which library and which version used.
     *
     * @param string $userId
     *    A string identifying the remote end user, often an UUID.
     *
     * @param string|null $userIp
     *    The IP from where the end user connection originates.
     *
     * @param string|null $userAgent
     *    User-Agent of the browser the end user is operating.
     *
     * @param string|null $referer
     *    The Referer header from the end user.
     */
    public function __construct(
        public UserInitiatedApi $userInitiatedApi,
        public OtherApi $otherApi,
        public string $apiVersion,
        public string $libVersion,
        public string $apiKey,
        public string $userId,
        public ?string $userIp,
        public ?string $userAgent,
        public ?string $referer,
    ) {
    }
}
